// Confirms the incoming item is a well-formed Decision Contract
// (docs/contracts/decision-contract.md) before any report-building runs.
// This is the only node that validates the contract's envelope shape -
// 'Build Report Contract' trusts it completely.
const STAGE = 'documentation_agent';
const WORKFLOW_VERSION = '1.0';
const VALID_VERDICT_STATUSES = ['PASS', 'FAIL', 'BLOCKED', 'MANUAL_REVIEW'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

// ERROR payloads produced upstream (Decision Orchestrator, or anything
// earlier) are not Decision Contracts and must not be re-validated as
// one - pass them through unchanged, same convention as every prior
// workflow.
if (item && item.status === 'ERROR') {
  return { json: item };
}

if (typeof item !== 'object' || item === null || Array.isArray(item)) {
  return { json: errorPayload(
    'INVALID_DECISION_CONTRACT',
    'Decision Contract must be a JSON object',
    { received_type: Array.isArray(item) ? 'array' : typeof item }
  ) };
}

const requiredFields = [
  'workflow_version', 'contract_version', 'request_id', 'response_id',
  'test_case', 'verdict', 'decision_basis', 'metadata'
];
const missingFields = requiredFields.filter((field) => item[field] === undefined);

if (missingFields.length > 0) {
  return { json: errorPayload(
    'INVALID_DECISION_CONTRACT',
    `Decision Contract is missing required field(s): ${missingFields.join(', ')}`,
    { missing_fields: missingFields, request_id: item.request_id || null }
  ) };
}

const v = item.verdict;
if (typeof v !== 'object' || v === null || Array.isArray(v) ||
    !VALID_VERDICT_STATUSES.includes(v.status) ||
    typeof v.confidence !== 'number' || v.confidence < 0 || v.confidence > 1 ||
    typeof v.reasoning !== 'string' ||
    !Array.isArray(v.evidence) || v.evidence.length === 0 ||
    typeof v.next_action !== 'string') {
  return { json: errorPayload(
    'INVALID_DECISION_CONTRACT',
    'Decision Contract verdict must be an object with a valid status/confidence/reasoning/evidence/next_action',
    { request_id: item.request_id }
  ) };
}

const db = item.decision_basis;
if (typeof db !== 'object' || db === null || Array.isArray(db) || typeof db.tier !== 'string') {
  return { json: errorPayload(
    'INVALID_DECISION_CONTRACT',
    'Decision Contract decision_basis must be an object with a tier',
    { request_id: item.request_id }
  ) };
}

if (typeof item.metadata !== 'object' || item.metadata === null || Array.isArray(item.metadata) ||
    typeof item.metadata.decided_at !== 'string') {
  return { json: errorPayload(
    'INVALID_DECISION_CONTRACT',
    'Decision Contract metadata must be an object with decided_at',
    { request_id: item.request_id }
  ) };
}

return { json: item };

// Build Report Contract - the Documentation Agent's only real work.
// Every value below is either carried forward unchanged from the
// Decision Contract or derived from it through a fixed, deterministic
// template. No AI call, no free-form generation, no renderer-specific
// (Excel/PDF/Sheets/Jira/dashboard) logic - see docs/contracts/
// report-contract.md and the Scope Note sticky.
const REPORT_WORKFLOW_VERSION = '1.0';
const REPORT_VERSION = '1.0';

// Evidence entries this project's producers (Decision Engine tiers,
// the Decision Agent prompt's Rule 4) render as 'field: value' - see
// 05-decision-orchestrator.json's Ground Evidence FIELD_VALUE_PATTERN.
// Used only to pick out the single most relevant entry for
// actual_result; evidence_summary below always uses the full set.
const FIELD_VALUE_PATTERN = /^([a-zA-Z_][\w.]*)\s*:\s*(.*)$/;
const ACTUAL_RESULT_FIELDS = ['actual_status', 'transport.status', 'status_code'];

const TESTER_NOTES = {
  PASS: 'No action needed - the actual result satisfied the expected result.',
  FAIL: 'Investigate this failure - the actual result contradicted the expected result.',
  BLOCKED: 'No response was received for this test case. Re-run once the target API/environment is reachable; this is not a statement about the API under test.',
  MANUAL_REVIEW: 'Requires manual review before this verdict is treated as final - confidence fell below the trust threshold, evidence was insufficient, or a hallucination guard rejected part of the automated judgment.'
};

function findActualResult(evidence) {
  for (const raw of evidence) {
    const match = FIELD_VALUE_PATTERN.exec(raw.trim());
    if (match && ACTUAL_RESULT_FIELDS.includes(match[1])) {
      return raw;
    }
  }
  // No recognizable field/value entry - fall back to the first evidence
  // entry rather than inventing a summary; still real, structured
  // evidence the verdict already rested on.
  return evidence[0];
}

function renderDecisionBasis(decisionBasis) {
  let rendered = `tier: ${decisionBasis.tier}`;
  if (decisionBasis.model_version) {
    rendered += `, model: ${decisionBasis.model_version}`;
  }
  if (decisionBasis.prompt_version) {
    rendered += `, prompt: ${decisionBasis.prompt_version}`;
  }
  return rendered;
}

function renderExecutionNotes(decisionBasis, decidedAt) {
  const basisText = decisionBasis.tier === 'ai_assisted'
    ? `an AI-assisted judgment (model: ${decisionBasis.model_version}, prompt: ${decisionBasis.prompt_version})`
    : `a deterministic rule (${decisionBasis.tier}), no AI call made`;
  return `Decision reached at ${decidedAt} via ${basisText}.`;
}

const item = $input.item.json;
const verdict = item.verdict;
const decisionBasis = item.decision_basis;
const decidedAt = item.metadata.decided_at;

return { json: {
  workflow_version: REPORT_WORKFLOW_VERSION,
  report_version: REPORT_VERSION,
  test_case: item.test_case,
  decision: {
    request_id: item.request_id,
    response_id: item.response_id,
    verdict,
    decision_basis: decisionBasis,
    decided_at: decidedAt
  },
  report: {
    status: verdict.status,
    actual_result: findActualResult(verdict.evidence),
    reasoning: verdict.reasoning,
    tester_notes: TESTER_NOTES[verdict.status],
    execution_notes: renderExecutionNotes(decisionBasis, decidedAt),
    confidence: verdict.confidence,
    decision_basis: renderDecisionBasis(decisionBasis),
    manual_review: verdict.status === 'MANUAL_REVIEW',
    evidence_summary: verdict.evidence.join('; '),
    execution_time: decidedAt,
    metadata: {
      documented_at: new Date().toISOString(),
      source_workflow: '05-decision-orchestrator',
      next_workflow: null
    }
  }
} };
